
select distinct asn.asn_order_num asn单, asn.po_order_code 采购单,
                -- ASN单状态
                CASE asn.order_status
                    WHEN 1 THEN '订单创建'
                    WHEN 2 THEN '部分收货'
                    WHEN 3 THEN '收货完成'
                    WHEN 4 THEN 'ASN单关闭'
                    ELSE '未知'
                    END AS ASN单状态,

-- 收货状态（是否实际收货完成）
                CASE asn.order_receive_status
                    WHEN 1 THEN '是'
                    WHEN 0 THEN '否'
                    ELSE '未知'
                    END AS 收货状态,
                if(asn.receive_start_time ='1970-01-01 08:00:01', null,asn.receive_start_time)  收货开始时间,
-- 收货拦截
                CASE asn.receivable_status
                    WHEN 1 THEN '是'
                    WHEN 0 THEN '否'
                    ELSE '未知'
                    END AS 收货拦截,

-- 质检状态
                CASE asn.order_qc_status
                    WHEN 1 THEN '未质检'
                    WHEN 2 THEN '质检中'
                    WHEN 3 THEN '质检完成'
                    ELSE '未知'
                    END AS 质检状态,

-- 上架状态
                CASE asn.order_shelve_status
                    WHEN 1 THEN '未上架'
                    WHEN 2 THEN '部分上架'
                    WHEN 3 THEN '上架完成'
                    ELSE '未知'
                    END AS 上架状态,

                a.location_code 当前库位
from dwd.dwd_fact_mk_wms_wmsin_asn_order_di as asn
     join dwd.dwd_fact_pcct_purchase_order_line_df as po on po.po_order_code = asn.po_order_code and po.sku = asn.sku
     left join dwd.dwd_dim_mk_wms_wmsin_parent_batch_di as b on asn.asn_order_num = b.asn_order_num and b.record_status = 1
     left join dws.dws_mk_wms_stock_batch_df as a on b.parent_batch_code = a.parent_batch_code and b.record_status = 1
